insert into public.volunteer_roles (title, commitment, training, blurb, sort_order) values
  ('Timekeeper', '~2 galas per season', '30-min poolside briefing', 'The classic first step. Sit poolside with a stopwatch, time your lane, enjoy the best seats in the house. No experience needed — we''ll show you everything before the first race.', 0),
  ('Licensed Official (Judge Level 1+)', 'A few meets per year', 'Free Swim England course + mentored poolside hours', 'Progress from Timekeeper to Judge, Starter and beyond. The club funds your training, and every licensed meet we enter needs us to supply officials — you make racing possible.', 1),
  ('Team Manager', 'League rounds & selected meets', 'Swim England Team Manager modules (funded)', 'Look after our swimmers on poolside at away galas — registration, marshalling, and keeping the team fed, warm and where they need to be.', 2),
  ('Meet Helpers (home galas)', 'Ad-hoc — sign-up sheets per event', 'None needed', 'Home meets need runners, refreshments, spectator desk and set-up/pack-down crews. Great for family members who want to help without a regular commitment.', 3),
  ('Committee & Welfare', 'Monthly meeting + role duties', 'Role handover + Wavepower training for welfare', 'Treasurer, secretary, membership, welfare officer — the roles that keep the club running and safe. Talk to any committee member if you''re curious.', 4);
